-- 16 authentic guided workshops with checkable steps and transparent evaluation criteria.
-- Preserves previously recorded learner submissions, achievements and XP.
create table public.mission_guides (
 mission_id uuid primary key references public.missions(id) on delete cascade,
 brief text not null check (char_length(brief) between 40 and 1200),
 steps jsonb not null check (jsonb_typeof(steps)='array' and jsonb_array_length(steps) between 2 and 8),
 rubric jsonb not null check (jsonb_typeof(rubric)='array' and jsonb_array_length(rubric) between 2 and 8),
 hint text not null,
 resource_url text not null check (resource_url ~ '^https://'),
 updated_at timestamptz not null default now()
);
create table public.workshop_steps (
 learner_id uuid not null references public.profiles(id) on delete cascade,
 mission_id uuid not null references public.mission_guides(mission_id) on delete cascade,
 step_number integer not null check(step_number between 1 and 8),
 completed_at timestamptz not null default now(),
 primary key(learner_id,mission_id,step_number)
);
create index workshop_steps_mission on public.workshop_steps(mission_id);
create function public.validate_workshop_step()
returns trigger language plpgsql security definer set search_path=''
as $$
declare v_step_count integer;
begin
  if auth.uid() is null or new.learner_id<>auth.uid()
      or not exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='learner')
  then raise exception 'Learner permissions required'; end if;
  select jsonb_array_length(g.steps) into v_step_count
    from public.mission_guides g join public.missions m on m.id=g.mission_id
    where g.mission_id=new.mission_id and m.published;
  if v_step_count is null or new.step_number>v_step_count
  then raise exception 'Invalid workshop step'; end if;
  if exists(
    select 1 from public.mission_prerequisites req
    where req.mission_id=new.mission_id and not exists(
      select 1 from public.xp_ledger x
      where x.learner_id=new.learner_id and x.mission_id=req.prerequisite_id
    )
  ) then raise exception 'Prerequisite not approved'; end if;
  return new;
end;
$$;
create trigger before_workshop_step_insert before insert on public.workshop_steps
  for each row execute function public.validate_workshop_step();
revoke all on function public.validate_workshop_step() from public,anon,authenticated;
alter table public.mission_guides enable row level security;
alter table public.workshop_steps enable row level security;
create policy mission_guides_read on public.mission_guides for select to authenticated
  using(exists(select 1 from public.missions m where m.id=mission_id and m.published));
create policy workshop_steps_read on public.workshop_steps for select to authenticated
  using(learner_id=(select auth.uid()) or (select public.is_trainer()));
create policy workshop_steps_insert on public.workshop_steps for insert to authenticated
  with check (learner_id=(select auth.uid()));
revoke insert,update,delete on public.mission_guides from anon,authenticated;
revoke update,delete on public.workshop_steps from anon,authenticated;
with guide_data as (
  select * from jsonb_to_recordset($guides$[{"title":"Créer une page HTML structurée","brief":"Tu développes la page de présentation d'un futur service Zenithis. Le résultat doit être lisible, utilisable au clavier et prêt à recevoir du CSS.","steps":[["Préparer le dépôt","Crée index.html et README.md. Décris le public visé et l'objectif de la page.","Dépôt avec une arborescence claire."],["Construire la structure","Ajoute header, nav, main, trois sections et footer. Utilise un seul h1 et une hiérarchie de titres cohérente.","Page HTML sémantique complète."],["Créer une interaction","Ajoute un formulaire de contact avec labels, types d'input adaptés et champs obligatoires.","Formulaire navigable au clavier."],["Tester et publier","Vérifie les liens, les libellés et la navigation clavier. Publie le dépôt et une capture ou démo.","URL publique et README indiquant les tests."]],"rubric":["Structure HTML sémantique et hiérarchie des titres","Labels et navigation clavier fonctionnels","Contenu clair et liens utilisables","Code et instructions de reproduction présents dans le dépôt"],"hint":"Commence par la structure, pas par les couleurs.","resource":"https://developer.mozilla.org/fr/docs/Web/HTML"},{"title":"Transformer la page en interface responsive","brief":"Tu reprends ta page HTML et l'adaptes à un téléphone puis à un grand écran sans compromettre son accessibilité.","steps":[["Définir les styles","Crée style.css et mets en place variables de couleur, tailles de police et espacements cohérents.","Styles de base centralisés."],["Construire la mise en page","Utilise Flexbox ou Grid pour le menu et les sections, avec largeur maximale du contenu.","Mise en page desktop stable."],["Adapter au mobile","Conçois d'abord pour 360 px, puis ajoute des media queries pertinentes. Évite le défilement horizontal.","Captures mobile et desktop."],["Contrôler la qualité","Teste la lisibilité, le contraste, les champs du formulaire et l'affichage à 360 px, 768 px et 1280 px.","Checklist responsive dans README."]],"rubric":["Aucun débordement horizontal","Mise en page adaptée à trois largeurs d'écran","Typographie et contrastes lisibles","Formulaire et navigation utilisables sur mobile"],"hint":"Élargis progressivement l'écran et corrige uniquement ce qui casse.","resource":"https://developer.mozilla.org/fr/docs/Web/CSS"},{"title":"Programmer une liste de tâches","brief":"Tu construis un gestionnaire de tâches utilisable sans framework, en JavaScript natif.","steps":[["Définir les scénarios","Liste les états attendus : vide, tâches actives, tâches terminées et erreurs de saisie.","Trois cas d'utilisation écrits dans README."],["Ajouter et afficher","Écris les fonctions de création et de rendu. Valide une tâche vide ou constituée d'espaces.","Ajout fonctionnel depuis le formulaire."],["Terminer et supprimer","Implémente une case pour terminer la tâche et un bouton de suppression associé à chaque élément.","Liste modifiable sans rechargement."],["Tester les cas limites","Teste cinq ajouts, un doublon, une suppression, l'état vide et le clavier.","Démo publique et note de tests."]],"rubric":["Ajout et affichage fiables","Modification de l'état et suppression opérationnelles","Gestion des saisies invalides","Code lisible et démonstration reproductible"],"hint":"Une fonction = une responsabilité. Sépare la donnée de son affichage.","resource":"https://developer.mozilla.org/fr/docs/Web/JavaScript"},{"title":"Sauvegarder les tâches","brief":"Tu transformes la liste de tâches précédente en mini-produit persistant, utilisable après actualisation de la page.","steps":[["Modéliser le stockage","Définis le format JSON avec identifiant, titre et statut. Prépare une valeur initiale vide.","Schéma d'un exemple de tâche documenté."],["Charger les données","Lis localStorage au démarrage avec gestion de JSON absent ou invalide.","Restauration des tâches au chargement."],["Enregistrer les modifications","Sauvegarde après ajout, modification et suppression. Évite les données incohérentes.","Persistance après rafraîchissement."],["Tester et expliquer","Teste plusieurs cycles d'utilisation, le stockage vidé et les limites entre navigateurs.","Démo avec README expliquant les limites de localStorage."]],"rubric":["Données restaurées sans erreur","Chaque action persiste correctement","Gestion des données invalides","Limites du stockage local expliquées"],"hint":"Essaie de charger une valeur corrompue : ton application ne doit pas planter.","resource":"https://developer.mozilla.org/fr/docs/Web/API/Window/localStorage"},{"title":"Construire une interface avec React","brief":"Tu fais évoluer ton mini-produit vers une interface en composants React réutilisables.","steps":[["Initialiser React","Crée un projet React avec un outil moderne et explique sa structure.","Dépôt React fonctionnel."],["Découper l'interface","Crée au moins quatre composants : en-tête, formulaire, liste et élément de tâche.","Arborescence et responsabilités documentées."],["Passer des propriétés","Affiche des données d'exemple avec props et clés stables pour chaque élément.","Liste React sans avertissement de clé."],["Préparer la livraison","Nettoie les composants inutilisés, teste les trois tailles d'écran et publie.","Démo fonctionnelle et README de démarrage."]],"rubric":["Découpage en composants cohérent","Props et listes React correctes","Aucune erreur bloquante en console","Interface responsive et documentée"],"hint":"Ne reproduis pas tout dans un seul composant.","resource":"https://fr.react.dev/learn"},{"title":"Gérer les interactions et l'état","brief":"Tu rends l'interface React réellement interactive en gérant l'état, les actions et les formulaires.","steps":[["Ajouter les états","Définis tâches, filtre et texte du formulaire avec useState.","États identifiables dans le code."],["Construire les interactions","Ajoute création, terminaison, suppression et filtrage des tâches.","Interactions sans manipulation directe du DOM."],["Valider le formulaire","Empêche les tâches vides et affiche un message clair à l'utilisateur.","Erreurs de saisie visibles."],["Tester les transitions","Teste filtrage, plusieurs changements successifs et retour à une liste vide.","Démo et scénarios de test documentés."]],"rubric":["État React bien maîtrisé","Actions fiables et résultat immédiatement visible","Validation des saisies","Scénarios limites reproductibles"],"hint":"Évite de dupliquer des données dérivées dans l'état.","resource":"https://fr.react.dev/learn/managing-state"},{"title":"Créer une API REST documentée","brief":"Tu développes une API de tâches indépendante de l'interface, avec réponses HTTP cohérentes.","steps":[["Concevoir les routes","Définis GET, POST, PATCH et DELETE sur /tasks. Rédige les objets attendus.","Contrat d'API dans README."],["Implémenter le CRUD","Développe les routes avec un stockage temporaire pour commencer.","Quatre actions HTTP démontrables."],["Valider les requêtes","Rejette identifiants inconnus et données invalides. Utilise des statuts HTTP adaptés.","Réponses 400, 404 et 201 testées."],["Documenter et tester","Ajoute des exemples curl ou un fichier de requêtes et explique comment lancer l'API.","Dépôt exécutable avec exemples."]],"rubric":["Routes REST cohérentes et complètes","Codes HTTP corrects","Validation des données entrantes","Documentation et tests des erreurs"],"hint":"Une API doit expliquer clairement pourquoi une requête échoue.","resource":"https://developer.mozilla.org/fr/docs/Web/HTTP"},{"title":"Relier React à une API","brief":"Tu raccordes ton interface au serveur pour consulter et modifier des tâches au travers du réseau.","steps":[["Brancher la lecture","Remplace les données fictives par un GET de l'API et affiche un état de chargement.","Liste chargée depuis l'API."],["Relier les actions","Connecte ajout, statut et suppression aux routes REST.","Modifications envoyées au serveur."],["Traiter les erreurs","Affiche une erreur réseau compréhensible et une option de nouvel essai.","Message d'erreur et récupération sans rechargement."],["Valider de bout en bout","Teste une création, une modification, une suppression et une coupure volontaire du serveur.","Démo de parcours complet et note de tests."]],"rubric":["Données réellement récupérées depuis l'API","Écritures côté serveur fiables","Chargement et erreurs visibles","Scénario utilisateur complet démontré"],"hint":"Ne montre pas une confirmation de succès avant la réponse du serveur.","resource":"https://developer.mozilla.org/fr/docs/Web/API/Fetch_API"},{"title":"Persister les données avec PostgreSQL","brief":"Tu remplaces le stockage temporaire du serveur par des données réellement persistantes et liées.","steps":[["Dessiner le modèle","Définis utilisateurs et tâches, clés primaires, clé étrangère et contraintes.","Schéma SQL avec commentaires."],["Créer les tables","Écris une migration SQL reproductible et des données de test.","Tables et contraintes créées."],["Relier l'API","Connecte les routes CRUD à PostgreSQL avec requêtes paramétrées.","Données conservées au redémarrage."],["Tester l'intégrité","Teste une relation inexistante, un champ invalide et la suppression d'une tâche.","Tests SQL et instructions de réinitialisation."]],"rubric":["Schéma relationnel cohérent","Intégrité et contraintes appliquées","API reliée à PostgreSQL","Migrations et tests reproductibles"],"hint":"Ne mets jamais un mot de passe de base de données dans ton dépôt.","resource":"https://www.postgresql.org/docs/current/tutorial.html"},{"title":"Sécuriser l'accès aux données","brief":"Tu ajoutes une identité utilisateur et tu t'assures que chacun ne peut accéder qu'à ses propres données.","steps":[["Ajouter une connexion","Crée une authentification testable et explique la gestion de la session.","Connexion et déconnexion opérationnelles."],["Protéger les routes","Vérifie l'identité côté serveur sur les opérations privées.","Routes protégées contre l'accès anonyme."],["Isoler les données","Filtre les tâches par propriétaire et configure les politiques d'accès pertinentes.","Utilisateur A incapable de lire les données de B."],["Auditer les accès","Teste requêtes sans session, session expirée et identifiant d'un autre utilisateur.","Preuves de tests et limites décrites."]],"rubric":["Authentification réellement fonctionnelle","Vérifications d'accès côté serveur","Séparation entre utilisateurs démontrée","Aucun secret exposé dans le dépôt"],"hint":"Un bouton masqué n'est pas une autorisation : le serveur doit refuser l'accès.","resource":"https://supabase.com/docs/guides/auth"},{"title":"Améliorer l'expérience et l'accessibilité","brief":"Tu passes d'un prototype fonctionnel à une expérience claire et accessible sur téléphone.","steps":[["Auditer les parcours","Observe les écrans vide, erreur, chargement et succès sur mobile.","Liste priorisée de problèmes UX."],["Corriger le mobile","Améliore menu, espacements, contrastes et zones tactiles à 360 px.","Captures avant/après sur mobile."],["Tester l'accessibilité","Navigue au clavier, vérifie labels, titres et messages d'erreur.","Checklist d'accessibilité remplie."],["Recueillir un retour","Fais tester le parcours principal à une personne et corrige deux difficultés observées.","Compte rendu court de la revue utilisateur."]],"rubric":["Parcours principal compréhensible","Responsive sans débordement","Clavier et libellés utilisables","Améliorations fondées sur des tests"],"hint":"Observe ce que fait la personne, pas seulement ce qu'elle dit.","resource":"https://developer.mozilla.org/fr/docs/Learn_web_development/Core/Accessibility"},{"title":"Tester et fiabiliser son application","brief":"Tu mets en place un contrôle qualité permettant de modifier le produit sans casser ses fonctions essentielles.","steps":[["Lister les cas critiques","Identifie connexion, création, édition, suppression et cas sans données.","Plan de test avec cas attendus."],["Écrire les tests","Ajoute des tests automatisés sur des fonctions pures et un parcours critique.","Suite de tests exécutable."],["Réparer deux défauts","Reproduis et corrige au moins deux problèmes rencontrés ou simulés.","Avant/après et références des corrections."],["Préparer la recette","Exécute la suite et documente les limites des tests restants.","Rapport de qualité concis."]],"rubric":["Cas métier principaux couverts","Tests automatisés reproductibles","Gestion d'erreurs solide","Rapport de recette clair et précis"],"hint":"Un test utile échoue quand le comportement attendu est cassé.","resource":"https://developer.mozilla.org/fr/docs/Learn_web_development/Extensions/Testing"},{"title":"Assembler un produit complet","brief":"Tu intègres interface, authentification et données dans un produit cohérent utilisable par une autre personne.","steps":[["Choisir la valeur métier","Formule le problème utilisateur, trois fonctionnalités prioritaires et un critère de réussite.","Présentation du produit dans README."],["Relier les modules","Assemble navigation, comptes, données et formulaire en un seul parcours.","Version bêta avec parcours complet."],["Tester avec deux comptes","Teste un utilisateur A et un utilisateur B sur des données distinctes.","Preuve de séparation des comptes."],["Publier la bêta","Mets à disposition une URL, un compte de test dédié ou une procédure de démo.","Lien de bêta et liste de fonctionnalités réellement livrées."]],"rubric":["Problème et fonctionnalités clairement définis","Produit utilisable de bout en bout","Deux profils correctement séparés","Bêta publiquement démontrable et documentée"],"hint":"Livre peu de fonctionnalités, mais termine-les réellement.","resource":"https://nextjs.org/learn"},{"title":"Déployer et superviser le produit","brief":"Tu rends ton application disponible en préproduction, avec un déploiement reproductible et des contrôles d'erreur.","steps":[["Préparer l'environnement","Sépare configuration locale et distante; dresse l'inventaire des variables sans secrets.","Fichier d'exemple des variables."],["Déployer en ligne","Connecte le dépôt et lance une construction Vercel sans erreurs bloquantes.","URL de préproduction accessible."],["Contrôler les scénarios","Vérifie une connexion et une opération CRUD sur l'URL déployée.","Recette de préproduction."],["Rédiger le runbook","Explique comment redéployer, consulter les logs et réagir à une erreur.","Procédure de déploiement documentée."]],"rubric":["Déploiement reproductible","Aucun secret commité","Parcours de production testé","Procédure de diagnostic claire"],"hint":"Une URL accessible ne suffit pas : vérifie les fonctionnalités liées à la base.","resource":"https://vercel.com/docs"},{"title":"Optimiser et documenter le produit","brief":"Tu prépares ton application pour une démonstration sérieuse grâce aux corrections de performance, de sécurité et de documentation.","steps":[["Mesurer le fonctionnement","Identifie un écran lent, un problème mobile et un risque de sécurité concret.","Liste des mesures et risques."],["Corriger et comparer","Améliore au moins deux points avec un constat avant/après.","Journal des modifications et résultats."],["Compléter la documentation","Ajoute guide de démarrage, architecture, variables nécessaires et guide utilisateur.","README final lisible par un tiers."],["Valider la qualité","Exécute la recette sur ordinateur et téléphone, et note les limites restantes.","Rapport final de contrôle qualité."]],"rubric":["Améliorations réellement mesurées","Documentation complète et utilisable","Contrôles de sécurité cohérents","Tests finaux et limites explicités"],"hint":"La documentation doit permettre à une autre personne de lancer le projet sans ton aide.","resource":"https://web.dev/learn/performance"},{"title":"Présenter son produit final","brief":"Tu défends ton produit comme un développeur professionnel : démonstration claire, choix justifiés et limites assumées.","steps":[["Préparer la narration","Présente le problème, le public visé et les trois bénéfices du produit.","Trame d'une présentation de cinq minutes."],["Montrer le parcours réel","Effectue la connexion, une action métier et l'affichage du résultat enregistré.","Démo fluide et reproductible."],["Expliquer les choix","Présente architecture, technologie, données, sécurité et compromis.","Schéma et décisions commentées."],["Livrer le dossier final","Fournis dépôt, URL, documentation, tests et trois améliorations futures.","Dossier de livraison final vérifiable."]],"rubric":["Démonstration d'un produit réellement fonctionnel","Clarté de l'architecture et des choix","Livrables et documentation complets","Réponses solides aux questions et limites identifiées"],"hint":"Répète ta démonstration avec une connexion réseau imparfaite et un plan de secours.","resource":"https://developer.mozilla.org/fr/docs/Learn_web_development"}]$guides$::jsonb)
  as g(title text,brief text,steps jsonb,rubric jsonb,hint text,resource text)
)
insert into public.mission_guides(mission_id,brief,steps,rubric,hint,resource_url)
select m.id,g.brief,g.steps,g.rubric,g.hint,g.resource
from guide_data g join public.missions m on m.title=g.title
on conflict(mission_id) do nothing;
